const e=[{id:"1",slug:"3-secrets-behind-singapore-public-trust-south-africa",title:"3 Secrets Behind Singapore's Public Trust—and How South Africa Can Rebuild It",excerpt:"South Africa faces a deep crisis of trust. Corruption scandals, service delivery failures, and inconsistent leadership have eroded public confidence. Singapore offers a different path.",image:"/assets/blog/post-1.png",category:"Governance",readTime:"6 min read"},{id:"2",slug:"5-principles-singapore-way-transform-south-africa-economy",title:"5 Principles From The Singapore Way That Could Transform South Africa's Economy",excerpt:"South Africa's economy is stuck: high unemployment, persistent inequality, unreliable energy supply. Singapore's economic principles offer a practical roadmap.",image:"/assets/blog/post-2.png",category:"Economics",readTime:"8 min read"},{id:"3",slug:"4-ways-singapore-housing-speaks-to-south-africa-informal-settlements",title:"4 Ways Singapore's Housing Story Speaks to South Africa's Informal Settlements",excerpt:"South Africa's informal settlements are one of its toughest challenges. Singapore's housing journey offers real, adaptable lessons.",image:"/assets/blog/post-3.png",category:"Housing",readTime:"7 min read"},{id:"4",slug:"5-singapore-lessons-south-africa-adapt-without-copying",title:"5 Singapore Lessons South Africa Can Adapt (Without Copying)",excerpt:"Adaptation is not imitation — here's how to draw the right lessons from Singapore's rise without copying what won't transfer.",image:"/assets/blog/post-4.png",category:"Adaptation",readTime:"6 min read"},{id:"5",slug:"from-cadres-to-competence-reforming-south-africa-public-service",title:"From Cadres to Competence: Reforming South Africa's Public Service With The Singapore Way",excerpt:"Meritocracy is not a Western concept. It's a human one. Here's how Singapore rebuilt its public service—and how South Africa could too.",image:"/assets/blog/post-5.png",category:"Governance",readTime:"7 min read"},{id:"6",slug:"fixing-whats-broken-tackling-service-delivery-failures",title:"Fixing What's Broken: Tackling Service Delivery Failures with the Singapore Way",excerpt:"Service delivery failure is one of the most visible symptoms of institutional breakdown. Singapore's approach to fixing systems offers practical tools.",image:"/assets/blog/post-6.png",category:"Policy",readTime:"6 min read"},{id:"7",slug:"embedding-long-term-thinking-higher-education",title:"Embedding Long-Term Thinking in South African Higher Education: Lessons from Singapore",excerpt:"Short-termism is an education killer. Singapore planned its university system decades ahead. Here's what that looks like in practice.",image:"/assets/blog/post-7.png",category:"Education",readTime:"8 min read"},{id:"8",slug:"why-copying-singapore-fails",title:"Why Copying Singapore Fails",excerpt:"Country after country has tried to copy Singapore. Most have failed. Not because the principles don't work—but because they copied the wrong thing.",image:"/assets/blog/post-8.png",category:"Framework",readTime:"5 min read"},{id:"9",slug:"meritocracy-simplified-opportunity-based-on-ability",title:"Meritocracy Simplified: Opportunity Based on Ability",excerpt:"Singapore's meritocracy is one of its most studied—and most misunderstood—principles. Here's what it actually means.",image:"/assets/blog/post-1.png",category:"Policy",readTime:"6 min read"},{id:"10",slug:"countries-already-adopting-singapores-lessons",title:"Countries Already Adopting Singapore's Lessons",excerpt:"Singapore's principles are being quietly adapted by nations across Africa, Asia, and the Middle East. Here's what they're doing.",image:"/assets/blog/post-2.png",category:"Case Studies",readTime:"9 min read"},{id:"11",slug:"teaching-the-singapore-way-leaders-of-tomorrow",title:"Teaching The Singapore Way to the Leaders of Tomorrow",excerpt:"How do you teach transformation? Singapore's story is increasingly finding its way into classrooms, leadership programs, and policy institutes.",image:"/assets/blog/post-3.png",category:"Education",readTime:"6 min read"},{id:"12",slug:"bridging-singapore-to-the-world",title:"Bridging Singapore to the World",excerpt:"How do we take lessons from a city-state of 5 million and make them relevant to diverse nations with very different histories and starting conditions?",image:"/assets/blog/post-4.png",category:"Framework",readTime:"5 min read"},{id:"13",slug:"how-to-adapt-singapores-lessons-in-your-country",title:"How to Adapt Singapore's Lessons in Your Country (Without Copying Them)",excerpt:"The adaptation process is the most important—and most neglected—part of using Singapore as a model. Here's a practical framework.",image:"/assets/blog/post-5.png",category:"Framework",readTime:"7 min read"},{id:"14",slug:"can-singapore-principles-work-in-my-country",title:"Can Singapore's Principles Work in My Country?",excerpt:"The most common question we get. The short answer is yes—but only if you understand what you're actually trying to replicate.",image:"/assets/blog/post-6.png",category:"Framework",readTime:"6 min read"},{id:"15",slug:"what-is-the-singapore-way",title:"What is The Singapore Way?",excerpt:"An introduction to the framework, the platform, and why Singapore's story matters for leaders, educators, and innovators across the Global Majority.",image:"/assets/blog/post-7.png",category:"Introduction",readTime:"4 min read"}];export{e as b};
